# Generation script for authentic metric catalog with 10Y horizons and 75+ statutory statement items
import json

def generate_catalog():
    catalog = []
    def add(key, name, cat, unit, tf=False, tfs=None, desc=""):
        item = {
            "key": key,
            "name": name,
            "category": cat,
            "unit": unit,
            "supports_timeframe": tf,
            "description": desc
        }
        if tf:
            item["timeframes"] = tfs or ["1y", "3y", "5y", "7y", "10y"]
            item["default_timeframe"] = "1y"
        catalog.append(item)

    # 1. Profit & Loss (Statutory Line Items & Derived - 25 items)
    add("sales", "Net Sales / Revenue", "Profit & Loss", "₹ Cr", True, desc="Total top-line net sales revenue from company operations.")
    add("raw_materials", "Raw Material Expenses", "Profit & Loss", "₹ Cr", True, desc="Direct cost of raw materials and inputs consumed.")
    add("employee_cost", "Employee Benefit Expenses", "Profit & Loss", "₹ Cr", True, desc="Salaries, wages, PF, and staff welfare expenses.")
    add("other_expenses", "Other Operating Expenses", "Profit & Loss", "₹ Cr", True, desc="Power, fuel, rent, admin, sales and distribution expenses.")
    add("expenses", "Operating Expenses", "Profit & Loss", "₹ Cr", True, desc="Total cost of raw materials, staff, operating, and overhead expenses.")
    add("operating_profit", "Operating Profit (EBITDA)", "Profit & Loss", "₹ Cr", True, desc="Earnings before interest, taxes, depreciation and amortization.")
    add("opm", "Operating Profit Margin (OPM %)", "Profit & Loss", "%", True, desc="Operating profit (EBITDA) divided by Net Sales as a percentage.")
    add("other_income", "Other Non-Operating Income", "Profit & Loss", "₹ Cr", True, desc="Non-core income from treasury deposits, dividends, and interest.")
    add("ebit", "EBIT / Operating Earnings", "Profit & Loss", "₹ Cr", True, desc="Earnings before interest and corporate taxes (Operating Profit - Depreciation).")
    add("interest", "Finance Costs / Interest", "Profit & Loss", "₹ Cr", True, desc="Interest charges and borrowing servicing costs paid on total debt.")
    add("depreciation", "Depreciation & Amortization", "Profit & Loss", "₹ Cr", True, desc="Annual non-cash write-down on tangible and intangible fixed assets.")
    add("pbt", "Profit Before Tax (PBT)", "Profit & Loss", "₹ Cr", True, desc="Gross pre-tax operating and other earnings before corporate income taxes.")
    add("tax_expense", "Tax Provision / Expense", "Profit & Loss", "₹ Cr", True, desc="Corporate income tax provisions for the period.")
    add("tax_pct", "Effective Tax Rate %", "Profit & Loss", "%", True, desc="Tax provision divided by Profit Before Tax.")
    add("net_profit", "Net Profit / PAT", "Profit & Loss", "₹ Cr", True, desc="Final bottom-line net profit after all taxes, interest, and depreciation.")
    add("npm", "Net Profit Margin (NPM %)", "Profit & Loss", "%", True, desc="Net profit (PAT) divided by Net Sales as a percentage.")
    add("nopat", "NOPAT (Net Operating Profit After Tax)", "Profit & Loss", "₹ Cr", True, desc="EBIT multiplied by (1 - Tax Rate); pure unleveraged operating profit.")
    add("eps", "Earnings Per Share (EPS)", "Profit & Loss", "₹", True, desc="Net profit divided by total outstanding equity shares.")
    add("cash_eps", "Cash Earnings Per Share (Cash EPS)", "Profit & Loss", "₹", True, desc="(Net profit + Depreciation) divided by total equity shares.")
    add("dividend_payout_pct", "Dividend Payout Ratio", "Profit & Loss", "%", True, desc="Percentage of net profits distributed to shareholders as dividends.")
    add("dividend_per_share", "Dividend Per Share (DPS)", "Profit & Loss", "₹", True, desc="Total dividends declared per equity share.")
    add("retention_ratio", "Retention Ratio %", "Profit & Loss", "%", True, desc="Percentage of earnings retained in the business (100 - Dividend Payout %).")
    add("gross_profit", "Gross Profit", "Profit & Loss", "₹ Cr", True, desc="Net sales minus cost of raw materials and direct manufacturing expenses.")
    add("gross_margin", "Gross Profit Margin %", "Profit & Loss", "%", True, desc="Gross profit divided by net sales as a percentage.")
    add("ebitda_margin", "EBITDA Margin %", "Profit & Loss", "%", True, desc="Operating EBITDA divided by net sales as a percentage.")

