    add("other_current_assets", "Other Current Assets", "Balance Sheet", "₹ Cr", False, desc="Prepaid expenses, GST input credits, and operational advances.")
    add("current_assets", "Total Current Assets", "Balance Sheet", "₹ Cr", False, desc="Sum of inventories, trade receivables, cash, and short-term assets.")
