    add("capital_employed", "Capital Employed", "Balance Sheet", "₹ Cr", False, desc="Total Net Worth plus Total Debt (long-term funds utilized in business).")
    add("invested_capital", "Invested Capital", "Balance Sheet", "₹ Cr", False, desc="Operating capital actively generating core returns.")
    add("net_debt", "Net Debt", "Balance Sheet", "₹ Cr", False, desc="Total Borrowings minus Cash and Liquid Bank Balances.")
    add("contingent_liabilities", "Contingent Liabilities", "Balance Sheet", "₹ Cr", False, desc="Off-balance sheet potential obligations and legal tax disputes.")
    add("net_fixed_assets_to_total_assets", "Net Fixed Assets to Total Assets %", "Balance Sheet", "%", False, desc="Proportion of company balance sheet tied up in physical operating assets.")

